glsl:
float sdf(vec3 pos) {
    float x = pos.x, y = pos.y, z = pos.z;
    // Domain twist for richer structure
    float a = 0.1 * z;
    float ca = cos(a), sa = sin(a);
    float xw = x*ca - y*sa;
    float yw = x*sa + y*ca;

    // Multi-scale gyroid: coarse + fine blended
    float s1 = 3.0, s2 = 5.0;
    float f1 = sin(s1*xw)*cos(s1*yw) + sin(s1*yw)*cos(s1*z) + sin(s1*z)*cos(s1*xw);
    float f2 = sin(s2*xw)*cos(s2*yw) + sin(s2*yw)*cos(s2*z) + sin(s2*z)*cos(s2*xw);

    // Lipschitz-normalised signed distance (gradient bound = s*sqrt(3))
    float d1 = abs(f1) / (s1 * 1.7320508);
    float d2 = abs(f2) / (s2 * 1.7320508);

    // Smooth union of two scales
    float k = 0.08;
    float h = max(k - abs(d1 - d2), 0.0) / k;
    float d = min(d1, d2) - h*h*k*0.25;

    return d - 0.1;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5*iResolution.xy) / iResolution.y;
    float t = iTime * 0.4 + 1.2;
    vec3 ro = vec3(3.0*cos(t), 0.8*3.0, 3.0*sin(t));
    vec3 ww = normalize(-ro);
    vec3 uu = normalize(cross(ww, vec3(0.0, 1.0, 0.0)));
    vec3 vv = cross(uu, ww);
    vec3 rd = normalize(uv.x*uu + uv.y*vv + 1.7*ww);

    float d = 0.001, max_d = 12.0;
    for (int i = 0; i < 96; i++) {
        float h = sdf(ro + d*rd);
        if (abs(h) < 0.0015*d || d > max_d) break;
        d += h * 0.75;
    }

    vec3 col = vec3(0.04, 0.02, 0.07);
    if (d < max_d) {
        vec3 p = ro + d*rd;
        float e = 0.001;
        vec3 n = normalize(vec3(
            sdf(p+vec3(e,0,0)) - sdf(p-vec3(e,0,0)),
            sdf(p+vec3(0,e,0)) - sdf(p-vec3(0,e,0)),
            sdf(p+vec3(0,0,e)) - sdf(p-vec3(0,0,e))
        ));
        vec3 ld = normalize(vec3(1.5, 2.0, -0.5));
        float diff = max(dot(n, ld), 0.0);
        float spec = pow(max(dot(reflect(-ld, n), -rd), 0.0), 48.0) * 0.7;
        col = vec3(0.15, 0.55, 0.85)*diff + spec + vec3(0.08, 0.04, 0.12)*(1.0-diff);
        col *= exp(-d * 0.12);
    }
    fragColor = vec4(pow(clamp(col, 0.0, 1.0), vec3(0.4545)), 1.0);
}
